@Override // org.java_websocket.server.WebSocketServer
public void onOpen(WebSocket webSocket, ClientHandshake clientHandshake) {
    Log.d(TAG, "onOpen Connected...");
    Log.d(TAG, "onOpen Connected..." + clientHandshake.getResourceDescriptor());
    String resourceDescriptor = clientHandshake.getResourceDescriptor();
    if (!clientHandshake.getResourceDescriptor().isEmpty()) {
        if (resourceDescriptor.contains(HubConstant.PC9090)) {
            webSocketMap.put(webSocket, HubConstant.PC9090);
            return;
        }
        if (resourceDescriptor.contains(HubConstant.PC9091)) {
            webSocketMap.put(webSocket, HubConstant.PC9091);
            return;
        }
        if (resourceDescriptor.contains(HubConstant.PC8888)) {
            webSocketMap.put(webSocket, HubConstant.PC8888);
            return;
        } else if (resourceDescriptor.contains(HubConstant.APP8888)) {
            removeConn(HubConstant.APP8888);
            webSocketMap.put(webSocket, HubConstant.APP8888);
            return;
        } else {
            webSocketMap.put(webSocket, HubConstant.ALL8888);
            return;
        }
    }
    webSocketMap.put(webSocket, HubConstant.ALL8888);
}
